// Frames generated by execution/build_hero_frames.py. File names sort in frame order.
const urls = (files: Record<string, string>) =>
  Object.keys(files)
    .sort()
    .map((k) => files[k])

export const heroFrames = {
  large: urls(
    import.meta.glob<string>('../../../../assets/home-hero/seq/large/*.webp', {
      eager: true,
      query: '?url',
      import: 'default',
    }),
  ),
  small: urls(
    import.meta.glob<string>('../../../../assets/home-hero/seq/small/*.webp', {
      eager: true,
      query: '?url',
      import: 'default',
    }),
  ),
}

// The intact jade, during its hold (source frame 122 of 240).
export const jadeStill = heroFrames.large[61]
